          "op": "if_visible",
          "target": "guests_entry",
          "then": [
            {
              "id": "tap_guests",
              "op": "tap",
              "target": "guests_entry"
            },
            {
              "id": "set_adults",
              "op": "set_stepper",
              "value_anchor": "adults_value",
              "plus": "adults_plus",
              "minus": "adults_minus",
              "value": "{adults}",
              "max_taps": 16
            },
            {
              "id": "apply_guests",
              "op": "if_visible",
              "target": "date_apply_button",
              "then": [
                {
                  "id": "tap_apply_guests",
                  "op": "tap",
                  "target": "date_apply_button"
                }
              ]
            }
          ]
        },
        {
          "id": "search",
          "op": "if_visible",
          "target": "search_button",
          "then": [
            {
              "id": "tap_search",
              "op": "tap",
              "target": "search_button"
            }
          ]
        },
        {
          "id": "wait_results",
          "op": "wait_for",
          "target": "result_list",
          "timeout_ms": 15000
        },
        {
          "id": "collect_results",
          "op": "collect_list",
          "list": "result_list",
          "item": "result_item",
          "fields": {
            "name": "result_name",
            "price": "result_price",
            "rating": "result_rating",
            "ad": "result_ad_badge"
