      "version": 1,
      "risk": "R3",
      "computed_commit": "R3",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "지난 주문 재주문",
        "en": "Reorder a past order",
        "ja": "前回の注文を再注文",
        "zh-TW": "重新訂購"
      },
      "summary_ko": "배달의민족의 주문내역에서 {store_keyword} 가게의 최근 주문(키워드가 없으면 사용자가 선택)을 찾아 재주문을 누르고, 장바구니 확인 후 결제 버튼은 사용자가 직접 누르게 한다.",
      "params": {
        "store_keyword": {
          "type": "string",
          "required": false,
          "desc": "가게 이름 키워드. 없으면 목록에서 사용자가 선택"
        }
      },
      "utterances": {
        "ko": [
          "배달의민족에서 {store_keyword} 지난번이랑 똑같이 시켜줘"
        ]
      },
      "script_ko": {
        "ko": [
          "1. 배달의민족 앱 실행 (첫 화면으로 초기화)",
          "2. '주문내역' 탭 선택",
          "3. 파라미터 {store_keyword}가 있으면",
          "   → 그렇다면:",
          "    3.1. 목록에서 [가게명]에 '{store_keyword}'가 포함된 항목 찾기 — 여러 개면 첫 항목(주문내역은 최신순 정렬이므로 가장 최근 주문(결정론적)), 없으면 중단 → $order",
          "   → 아니라면:",
          "    3.1. 목록을 아래로 스크롤하며 [store, menu, date] 수집 — 10개 모이면 멈춤 → $orders",
          "    3.2. [사용자 선택] $orders을 보여주고 사용자가 직접 고름 → $order",
          "4. '같은 메뉴 담기'가 보이면",
          "   → 그렇다면:",
          "    4.1. '같은 메뉴 담기' 버튼 누르기 ($order 안에서)",
          "   → 아니라면:",
          "    4.1. 선택된 항목($order) 누르기",
          "    4.2. '같은 메뉴 담기' 버튼 누르기",
          "5. '장바구니 보기' 버튼 누르기",
          "6. 목록을 아래로 스크롤하며 [title, price] 수집 — 목록 끝까지 → $cart",
          "7. [사용자 확인] \"장바구니 {cart.count}개 메뉴로 주문 화면으로 이동합니다. 결제는 아직 되지 않습니다.\" — 표시: $cart.title / 취소하면 중단",
          "8. '배달 주문하기' 버튼 누르기",
          "9. '결제수단' 표시 대기 (최대 10초)",
          "10. [배송지] 읽기 → $address",
          "11. [합계 금액] 읽기 → $total",
          "12. [사용자에게 인계] \"배달 주소 {address}, 결제금액 {total}입니다. 확인 후 결제 버튼을 직접 눌러 주세요.\" — 사용자가 '결제하기'를 직접 누름, '주문 접수' 확인까지 대기",
          "13. 종료 → 결과 $total (none)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_orders",
          "op": "tap",
          "target": "orders_tab"
        },
        {
          "id": "find_order",
          "op": "if_param",
          "param": "store_keyword",
          "then": [
            {
              "id": "match_order",
              "op": "find_in_list",
              "list": "order_list",
              "item": "order_item",
              "match": {
                "field": "order_item_store",
                "op": "contains",
                "value": "{store_keyword}"
              },
              "on_multiple": "first",
              "first_reason": "주문내역은 최신순 정렬이므로 가장 최근 주문(결정론적)",
              "on_none": "abort",
              "bind": "order"
            }
          ],
          "else": [
            {
              "id": "collect_orders",
              "op": "collect_list",
              "list": "order_list",
              "item": "order_item",
              "fields": {
                "store": "order_item_store",
                "menu": "order_item_menu",
                "date": "order_item_date"
              },
              "until": {
                "count": 10
              },
              "limit": 10,
              "max_scrolls": 4,
              "bind": "orders"
            },
            {
              "id": "choose_order",
              "op": "choose_by_user",
              "from": "$orders",
              "display": [
                "store",
                "menu",
                "date"
              ],
              "bind": "order"
            }
          ]
        },
        {
          "id": "tap_reorder",
          "op": "if_visible",
          "target": "reorder_button",
          "within": "$order",
          "then": [
            {
              "id": "reorder_in_list",
              "op": "tap",
              "target": "reorder_button",
              "within": "$order"
            }
          ],
          "else": [
            {
              "id": "open_order",
              "op": "tap",
              "target": "$order"
            },
            {
              "id": "reorder_in_detail",
              "op": "tap",
              "target": "reorder_button"
            }
          ]
        },
        {
          "id": "open_cart",
          "op": "tap",
          "target": "cart_entry"
        },
        {
          "id": "collect_cart",
          "op": "collect_list",
          "list": "cart_list",
          "item": "cart_item",
          "fields": {
            "title": "cart_item_title",
            "price": "cart_item_price"
          },
          "until": {
            "end_of_list": true
          },
          "limit": 30,
          "max_scrolls": 5,
          "bind": "cart"
        },
        {
          "id": "confirm_cart",
          "op": "confirm_with_user",
          "summary": {
            "ko": "장바구니 {cart.count}개 메뉴로 주문 화면으로 이동합니다. 결제는 아직 되지 않습니다.",
            "en": "Go to checkout with {cart.count} items? You will not be charged yet.",
            "ja": "カートの{cart.count}品で注文画面に進みます。まだ決済されません。",
            "zh-TW": "以{cart.count}項餐點前往結帳，尚未付款。"
          },
          "show": [
            "$cart.title"
          ]
        },
        {
          "id": "checkout",
          "op": "tap",
          "target": "checkout_button"
        },
        {
          "id": "wait_checkout",
          "op": "wait_for",
          "target": "checkout_marker",
          "timeout_ms": 10000
        },
        {
          "id": "read_address",
          "op": "read_text",
          "target": "order_address",
          "bind": "address"
        },
        {
          "id": "read_total",
          "op": "read_text",
          "target": "order_total",
          "bind": "total"
        },
        {
          "id": "handoff_pay",
          "op": "handoff_to_user",
          "instruction": {
            "ko": "배달 주소 {address}, 결제금액 {total}입니다. 확인 후 결제 버튼을 직접 눌러 주세요.",
            "en": "Delivering to {address}, total {total}. Review it and place the order yourself.",
            "ja": "お届け先{address}、合計{total}です。確認して注文確定をご自身で押してください。",
            "zh-TW": "外送地址{address}、總額{total}。請確認後自行下訂單。"
          },
          "commit_anchor": "place_order_button",
          "success_marker": "order_placed_marker",
          "timeout_ms": 600000
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$total"
          ],
          "present": "none"
        }
      ]
    },
    {
      "id": "food.track_order",
      "version": 1,
      "risk": "R0",
      "computed_commit": "R0",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "주문 진행 상황 확인",
        "en": "Track my food order",
        "ja": "注文の配達状況を確認",
        "zh-TW": "查詢外送進度"
      },
      "summary_ko": "배달의민족 앱을 열어 진행 중 주문 배너(없으면 주문내역 첫 주문)를 누르고 상태와 도착 예정 시간을 읽는다.",
      "params": {},
      "utterances": {
        "ko": [
          "배달의민족 음식 언제 와?",
          "배달의민족 배달 어디쯤이야?"
        ]
      },
      "script_ko": {
        "ko": [
          "1. 배달의민족 앱 실행 (첫 화면으로 초기화)",
          "2. '주문 현황'가 보이면",
          "   → 그렇다면:",
          "    2.1. '주문 현황' 누르기",
          "   → 아니라면:",
          "    2.1. '주문내역' 탭 선택",
          "    2.2. 목록에서 첫 번째 항목 찾기 — 여러 개면 첫 항목(가장 최근 주문(목록 첫 항목)), 없으면 중단 → $order",
          "    2.3. 선택된 항목($order) 누르기",
          "3. [진행 상태] 읽기 → $status",
          "4. [도착 예정] 읽기 → $eta",
          "5. 종료 → 결과 $status, $eta (summary)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "open_active",
          "op": "if_visible",
          "target": "active_order_banner",
          "then": [
            {
              "id": "tap_banner",
              "op": "tap",
              "target": "active_order_banner"
            }
          ],
          "else": [
            {
              "id": "go_orders",
              "op": "tap",
              "target": "orders_tab"
            },
            {
              "id": "latest",
              "op": "find_in_list",
              "list": "order_list",
              "item": "order_item",
              "on_multiple": "first",
              "first_reason": "가장 최근 주문(목록 첫 항목)",
              "on_none": "abort",
              "bind": "order"
            },
            {
              "id": "open_order",
              "op": "tap",
              "target": "$order"
            }
          ]
        },
        {
          "id": "read_status",
          "op": "read_text",
          "target": "order_status_text",
          "bind": "status"
        },
        {
          "id": "read_eta",
          "op": "read_text",
          "target": "order_eta_text",
          "bind": "eta"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$status",
            "$eta"
          ],
          "present": "summary"
        }
      ]
    },
    {
      "id": "food.order_history",
      "version": 1,
      "risk": "R0",
      "computed_commit": "R0",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "배달 주문 내역",
        "en": "Food order history",
        "ja": "注文履歴",
        "zh-TW": "外送訂單紀錄"
      },
      "summary_ko": "배달의민족의 주문내역 탭을 열고 최근 주문 {limit}건의 가게, 메뉴, 날짜, 상태를 읽는다.",
      "params": {
        "limit": {
          "type": "int",
          "default": 5,
          "min": 1,
          "max": 20
        }
      },
      "utterances": {
        "ko": [
          "배달의민족 최근에 뭐 시켰었지?"
        ]
      },
      "script_ko": {
        "ko": [
          "1. 배달의민족 앱 실행 (첫 화면으로 초기화)",
          "2. '주문내역' 탭 선택",
          "3. 목록을 아래로 스크롤하며 [store, menu, date, status] 수집 — {limit}개 모이면 멈춤 → $orders",
          "4. 종료 → 결과 $orders (table)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_orders",
          "op": "tap",
          "target": "orders_tab"
        },
        {
          "id": "collect_orders",
          "op": "collect_list",
          "list": "order_list",
          "item": "order_item",
          "fields": {
            "store": "order_item_store",
            "menu": "order_item_menu",
            "date": "order_item_date",
            "status": "order_item_status"
          },
          "until": {
            "count": "{limit}"
          },
          "limit": "{limit}",
          "max_scrolls": 5,
          "bind": "orders"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$orders"
          ],
          "present": "table"
        }
      ]
    }
  ]
}

