      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "open_search",
          "op": "tap",
          "target": "search_entry"
        },
        {
          "id": "type_query",
          "op": "input_text",
          "target": "search_input",
          "value": "{query}"
        },
        {
          "id": "submit",
          "op": "press_ime",
          "action": "search"
        },
        {
          "id": "collect_stores",
          "op": "collect_list",
          "list": "store_list",
          "item": "store_item",
          "fields": {
            "name": "store_name",
            "rating": "store_rating",
            "eta": "store_eta",
            "fee": "store_fee"
          },
          "until": {
            "count": "{limit}"
          },
          "limit": "{limit}",
          "max_scrolls": 5,
          "bind": "stores"
