          "then": [
            {
              "id": "reorder_in_list",
              "op": "tap",
              "target": "reorder_button",
              "within": "$order"
            }
          ],
          "else": [
            {
              "id": "open_order",
              "op": "tap",
              "target": "$order"
            },
            {
              "id": "reorder_in_detail",
              "op": "tap",
              "target": "reorder_button"
            }
          ]
        },
        {
          "id": "open_cart",
          "op": "tap",
          "target": "cart_entry"
        },
        {
          "id": "collect_cart",
          "op": "collect_list",
          "list": "cart_list",
          "item": "cart_item",
          "fields": {
            "title": "cart_item_title",
            "price": "cart_item_price"
          },
          "until": {
            "end_of_list": true
          },
          "limit": 30,
          "max_scrolls": 5,
          "bind": "cart"
        },
        {
          "id": "confirm_cart",
