          "    2.3. 선택된 항목($order) 누르기",
          "3. [진행 상태] 읽기 → $status",
          "4. [도착 예정] 읽기 → $eta",
          "5. 종료 → 결과 $status, $eta (summary)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "open_active",
          "op": "if_visible",
          "target": "active_order_banner",
