          "id": "read_eta",
          "op": "read_text",
          "target": "order_eta_text",
          "bind": "eta"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$status",
            "$eta"
          ],
          "present": "summary"
        }
      ]
