  "scenarios": [
    {
      "id": "food.search_restaurants",
      "version": 1,
      "risk": "R0",
      "computed_commit": "R0",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "메뉴/가게 검색",
        "en": "Search restaurants",
        "ja": "お店を検索",
        "zh-TW": "搜尋餐廳"
      },
      "summary_ko": "도어대시의 검색창에 {query}를 입력해 검색하고 상위 {limit}개 가게의 이름, 평점, 예상 배달시간, 배달비를 읽는다.",
      "params": {
        "query": {
          "type": "string",
          "required": true,
          "desc": "메뉴 또는 가게 이름"
        },
        "limit": {
          "type": "int",
          "default": 5,
          "min": 1,
          "max": 20
        }
      },
      "utterances": {
        "ko": [
          "도어대시에서 {query} 시킬 데 찾아줘"
        ],
        "en": [
          "Find {query} places on DoorDash"
        ]
      },
      "script_ko": {
        "en": [
          "1. 도어대시 앱 실행 (첫 화면으로 초기화)",
          "2. 'Search' 탭 선택",
          "3. 입력창에 {query} 입력",
          "4. 키보드 'search' 실행",
          "5. 목록을 아래로 스크롤하며 [name, rating, eta, fee] 수집 — {limit}개 모이면 멈춤 → $stores",
          "6. 종료 → 결과 $stores (table)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "open_search",
          "op": "tap",
          "target": "search_entry"
        },
        {
          "id": "type_query",
          "op": "input_text",
          "target": "search_input",
          "value": "{query}"
        },
        {
          "id": "submit",
          "op": "press_ime",
          "action": "search"
        },
        {
          "id": "collect_stores",
          "op": "collect_list",
          "list": "store_list",
          "item": "store_item",
          "fields": {
            "name": "store_name",
            "rating": "store_rating",
            "eta": "store_eta",
            "fee": "store_fee"
          },
          "until": {
            "count": "{limit}"
          },
          "limit": "{limit}",
          "max_scrolls": 5,
          "bind": "stores"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$stores"
          ],
          "present": "table"
        }
      ]
    },
    {
      "id": "food.add_menu_to_cart",
      "version": 1,
      "risk": "R1",
      "computed_commit": "R0",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "가게 메뉴 장바구니 담기",
        "en": "Add a menu item to cart",
        "ja": "メニューをカートに入れる",
        "zh-TW": "把餐點加入購物車"
      },
      "summary_ko": "도어대시에서 {restaurant}를 검색해 가게를 열고 {menu} 메뉴를 찾아 담는다. 필수 옵션이 있으면 사용자에게 넘긴다.",
      "params": {
        "restaurant": {
          "type": "string",
          "required": true
        },
        "menu": {
          "type": "string",
          "required": true
        }
      },
      "utterances": {
        "ko": [
          "도어대시에서 {restaurant} {menu} 장바구니에 담아줘"
        ],
        "en": [
          "Add {menu} from {restaurant} to my DoorDash cart"
        ]
      },
      "script_ko": {
        "en": [
          "1. 도어대시 앱 실행 (첫 화면으로 초기화)",
          "2. 'Search' 탭 선택",
          "3. 입력창에 {restaurant} 입력",
          "4. 키보드 'search' 실행",
          "5. 목록에서 [이름]에 '{restaurant}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $store",
          "6. 선택된 항목($store) 누르기",
          "7. 목록에서 [이름]에 '{menu}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $menu",
          "8. 선택된 항목($menu) 누르기",
          "9. 'Required'가 보이면",
          "   → 그렇다면:",
          "    9.1. [사용자에게 인계] \"필수 옵션을 선택하고 담기 버튼을 직접 눌러 주세요.\", 'View cart' 확인까지 대기",
          "   → 아니라면:",
          "    9.1. 'Add to cart' 버튼 누르기",
          "10. 'View cart' 표시 확인",
          "11. 종료 → 결과 $store.name, $menu.name (none)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "open_search",
          "op": "tap",
          "target": "search_entry"
        },
        {
          "id": "type_query",
          "op": "input_text",
          "target": "search_input",
          "value": "{restaurant}"
        },
        {
          "id": "submit",
          "op": "press_ime",
          "action": "search"
        },
        {
          "id": "pick_store",
          "op": "find_in_list",
          "list": "store_list",
          "item": "store_item",
          "match": {
            "field": "store_name",
            "op": "contains",
            "value": "{restaurant}"
          },
          "on_multiple": "ask_user",
          "on_none": "abort",
          "bind": "store"
        },
        {
          "id": "open_store",
          "op": "tap",
          "target": "$store"
        },
        {
          "id": "pick_menu",
          "op": "find_in_list",
          "list": "menu_list",
          "item": "menu_item",
          "match": {
            "field": "menu_name",
            "op": "contains",
            "value": "{menu}"
          },
          "on_multiple": "ask_user",
          "on_none": "abort",
          "bind": "menu"
        },
        {
          "id": "open_menu",
          "op": "tap",
          "target": "$menu"
        },
        {
          "id": "options",
          "op": "if_visible",
          "target": "menu_option_sheet",
          "then": [
            {
              "id": "handoff_options",
              "op": "handoff_to_user",
              "instruction": {
                "ko": "필수 옵션을 선택하고 담기 버튼을 직접 눌러 주세요.",
                "en": "Choose the required options and tap Add yourself.",
                "ja": "必須オプションを選んで追加してください。",
                "zh-TW": "請選擇必選項目後自行加入。"
              },
              "success_marker": "cart_added_marker",
              "timeout_ms": 180000
            }
          ],
          "else": [
