          "id": "wait_checkout",
          "op": "wait_for",
          "target": "checkout_marker",
          "timeout_ms": 10000
        },
        {
          "id": "read_address",
          "op": "read_text",
          "target": "order_address",
          "bind": "address"
        },
        {
          "id": "read_total",
          "op": "read_text",
          "target": "order_total",
          "bind": "total"
