    {
      "id": "shop.track_delivery",
      "version": 1,
      "risk": "R0",
      "computed_commit": "R0",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "배송 현황 확인",
        "en": "Track a delivery",
        "ja": "配送状況を確認",
        "zh-TW": "查詢物流"
      },
      "summary_ko": "11번가의 주문 목록에서 {item_keyword}가 포함된 최근 주문(없으면 가장 최근 주문)을 찾아 배송조회를 열고 상태, 도착 예정, 택배사를 읽는다.",
      "params": {
        "item_keyword": {
          "type": "string",
          "required": false,
          "desc": "주문 상품 키워드. 없으면 가장 최근 주문"
        }
      },
      "utterances": {
        "ko": [
          "11번가에서 시킨 {item_keyword} 어디쯤 왔어?",
          "11번가 배송 언제 와?"
        ]
      },
      "script_ko": {
        "ko": [
          "1. 11번가 앱 실행 (첫 화면으로 초기화)",
          "2. '나의11번가' 탭 선택",
          "3. '주문/배송조회' 버튼 누르기",
          "4. 목록 표시 대기 (최대 8초)",
          "5. 파라미터 {item_keyword}가 있으면",
          "   → 그렇다면:",
          "    5.1. 목록에서 [이름]에 '{item_keyword}'가 포함된 항목 찾기 — 여러 개면 첫 항목(주문 목록은 최신순 정렬이므로 가장 최근 주문을 선택(결정론적)), 없으면 중단 → $order",
          "   → 아니라면:",
          "    5.1. 목록에서 첫 번째 항목 찾기 — 여러 개면 첫 항목(가장 최근 주문(목록 첫 항목)), 없으면 중단 → $order",
          "6. '배송조회'가 보이면",
          "   → 그렇다면:",
          "    6.1. '배송조회' 버튼 누르기 ($order 안에서)",
          "   → 아니라면:",
          "    6.1. 선택된 항목($order) 누르기",
          "    6.2. '배송조회' 버튼 누르기",
          "7. [상태] 읽기 → $status",
          "8. [도착 예정] 읽기 → $eta",
          "9. [택배사] 읽기 → $carrier",
          "10. 종료 → 결과 $order.title, $status, $eta, $carrier (summary)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_my",
          "op": "tap",
          "target": "my_page_entry"
        },
        {
          "id": "go_orders",
          "op": "tap",
          "target": "orders_entry"
        },
        {
          "id": "wait_orders",
          "op": "wait_for",
          "target": "order_list",
          "timeout_ms": 8000
        },
        {
          "id": "find_order",
          "op": "if_param",
          "param": "item_keyword",
          "then": [
            {
              "id": "match_order",
              "op": "find_in_list",
              "list": "order_list",
              "item": "order_item",
              "match": {
                "field": "order_item_title",
                "op": "contains",
                "value": "{item_keyword}"
              },
              "on_multiple": "first",
              "first_reason": "주문 목록은 최신순 정렬이므로 가장 최근 주문을 선택(결정론적)",
              "on_none": "abort",
              "bind": "order"
            }
          ],
          "else": [
            {
              "id": "latest_order",
              "op": "find_in_list",
              "list": "order_list",
              "item": "order_item",
              "on_multiple": "first",
              "first_reason": "가장 최근 주문(목록 첫 항목)",
              "on_none": "abort",
              "bind": "order"
            }
          ]
        },
        {
          "id": "tap_track",
          "op": "if_visible",
          "target": "track_button",
          "within": "$order",
          "then": [
            {
              "id": "track_in_list",
              "op": "tap",
              "target": "track_button",
              "within": "$order"
            }
          ],
          "else": [
            {
              "id": "open_order",
              "op": "tap",
              "target": "$order"
            },
            {
              "id": "track_in_detail",
              "op": "tap",
              "target": "track_button"
            }
          ]
        },
        {
          "id": "read_status",
          "op": "read_text",
          "target": "tracking_status",
          "bind": "status"
        },
        {
          "id": "read_eta",
          "op": "read_text",
          "target": "tracking_eta",
          "bind": "eta"
        },
        {
          "id": "read_carrier",
          "op": "read_text",
          "target": "tracking_carrier",
          "bind": "carrier"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$order.title",
            "$status",
            "$eta",
            "$carrier"
          ],
          "present": "summary"
        }
      ]
    },
    {
