          "id": "open_order",
          "op": "tap",
          "target": "$order"
        },
        {
          "id": "tap_cancel",
          "op": "tap",
          "target": "cancel_return_button"
        },
        {
          "id": "handoff",
          "op": "handoff_to_user",
          "instruction": {
            "ko": "사유를 선택하고 신청 버튼을 직접 눌러 주세요.",
