      "risk": "R2",
      "computed_commit": "R2",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "텍스트 게시하기",
        "en": "Publish a text post",
        "ja": "テキストを投稿する",
        "zh-TW": "發佈文字貼文"
      },
      "summary_ko": "페이스북의 글쓰기 버튼을 누르고 {post_text}를 입력한 뒤, 공개 범위와 내용을 사용자에게 확인받고 게시한다.",
      "params": {
        "post_text": {
          "type": "text",
          "required": true,
          "max_len": 500
        }
      },
      "utterances": {
        "ko": [
          "페이스북에 \"{post_text}\"라고 올려줘"
        ],
        "en": [
          "Post \"{post_text}\" on Facebook"
        ],
        "zh-TW": [
          "在Facebook發文「{post_text}」"
        ]
      },
      "script_ko": {
        "en": [
          "1. 페이스북 앱 실행 (첫 화면으로 초기화)",
          "2. 'Home' 탭 선택",
          "3. 'What's on your mind?' 버튼 누르기",
          "4. 입력창 표시 대기 (최대 5초)",
          "5. 입력창에 {post_text} 입력",
          "6. [사용자 확인] \"아래 내용을 {app}에 공개 게시합니다.\" — 표시: {post_text} / 취소하면 중단",
          "7. 'Post' 버튼 누르기 ⟵ 커밋(R2)",
          "8. 종료 → 결과 없음 (none)"
        ],
        "zh-TW": [
          "1. 페이스북 앱 실행 (첫 화면으로 초기화)",
          "2. '首頁' 탭 선택",
          "3. '在想些什麼？' 버튼 누르기",
          "4. 입력창 표시 대기 (최대 5초)",
          "5. 입력창에 {post_text} 입력",
          "6. [사용자 확인] \"아래 내용을 {app}에 공개 게시합니다.\" — 표시: {post_text} / 취소하면 중단",
          "7. '發佈' 버튼 누르기 ⟵ 커밋(R2)",
          "8. 종료 → 결과 없음 (none)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_home",
          "op": "tap",
          "target": "tab_home"
        },
        {
          "id": "compose",
          "op": "tap",
          "target": "compose_entry"
        },
        {
          "id": "wait_compose",
          "op": "wait_for",
          "target": "compose_input",
          "timeout_ms": 5000
        },
        {
          "id": "type_post",
          "op": "input_text",
          "target": "compose_input",
          "value": "{post_text}"
        },
        {
          "id": "confirm",
          "op": "confirm_with_user",
          "summary": {
            "ko": "아래 내용을 {app}에 공개 게시합니다.",
            "en": "Publish this on {app}?",
            "ja": "次の内容を{app}に投稿します。",
            "zh-TW": "將在{app}發佈以下內容。"
          },
          "show": [
            "{post_text}"
          ]
        },
        {
          "id": "publish",
          "op": "tap",
          "target": "publish_button"
        },
        {
          "id": "done",
          "op": "end",
          "output": [],
          "present": "none"
        }
      ]
    }
  ]
}

