          "op": "end",
          "output": [
            "$total"
          ],
          "present": "none"
        }
      ]
    },
    {
      "id": "food.track_order",
      "version": 1,
      "risk": "R0",
      "computed_commit": "R0",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "주문 진행 상황 확인",
        "en": "Track my food order",
        "ja": "注文の配達状況を確認",
        "zh-TW": "查詢外送進度"
      },
      "summary_ko": "푸드판다 앱을 열어 진행 중 주문 배너(없으면 주문내역 첫 주문)를 누르고 상태와 도착 예정 시간을 읽는다.",
      "params": {},
      "utterances": {
        "ko": [
          "푸드판다 음식 언제 와?",
          "푸드판다 배달 어디쯤이야?"
        ],
        "zh-TW": [
          "foodpanda外送還要多久？"
        ]
      },
      "script_ko": {
        "zh-TW": [
          "1. 푸드판다 앱 실행 (첫 화면으로 초기화)",
          "2. '訂單進度'가 보이면",
          "   → 그렇다면:",
          "    2.1. '訂單進度' 누르기",
          "   → 아니라면:",
          "    2.1. '訂單' 탭 선택",
          "    2.2. 목록에서 첫 번째 항목 찾기 — 여러 개면 첫 항목(가장 최근 주문(목록 첫 항목)), 없으면 중단 → $order",
          "    2.3. 선택된 항목($order) 누르기",
          "3. [진행 상태] 읽기 → $status",
          "4. [도착 예정] 읽기 → $eta",
          "5. 종료 → 결과 $status, $eta (summary)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "open_active",
          "op": "if_visible",
          "target": "active_order_banner",
          "then": [
            {
              "id": "tap_banner",
              "op": "tap",
              "target": "active_order_banner"
            }
          ],
          "else": [
            {
              "id": "go_orders",
              "op": "tap",
              "target": "orders_tab"
            },
            {
              "id": "latest",
              "op": "find_in_list",
              "list": "order_list",
              "item": "order_item",
              "on_multiple": "first",
              "first_reason": "가장 최근 주문(목록 첫 항목)",
              "on_none": "abort",
              "bind": "order"
            },
            {
              "id": "open_order",
              "op": "tap",
              "target": "$order"
            }
          ]
        },
        {
          "id": "read_status",
          "op": "read_text",
          "target": "order_status_text",
          "bind": "status"
        },
        {
          "id": "read_eta",
          "op": "read_text",
          "target": "order_eta_text",
          "bind": "eta"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$status",
            "$eta"
          ],
          "present": "summary"
        }
      ]
    },
    {
      "id": "food.order_history",
      "version": 1,
      "risk": "R0",
      "computed_commit": "R0",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "배달 주문 내역",
        "en": "Food order history",
        "ja": "注文履歴",
        "zh-TW": "外送訂單紀錄"
      },
      "summary_ko": "푸드판다의 주문내역 탭을 열고 최근 주문 {limit}건의 가게, 메뉴, 날짜, 상태를 읽는다.",
      "params": {
        "limit": {
          "type": "int",
          "default": 5,
          "min": 1,
          "max": 20
        }
      },
      "utterances": {
        "ko": [
          "푸드판다 최근에 뭐 시켰었지?"
        ],
        "zh-TW": [
          "我最近在foodpanda點了什麼？"
        ]
      },
      "script_ko": {
        "zh-TW": [
          "1. 푸드판다 앱 실행 (첫 화면으로 초기화)",
          "2. '訂單' 탭 선택",
          "3. 목록을 아래로 스크롤하며 [store, menu, date, status] 수집 — {limit}개 모이면 멈춤 → $orders",
          "4. 종료 → 결과 $orders (table)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_orders",
          "op": "tap",
          "target": "orders_tab"
        },
        {
          "id": "collect_orders",
          "op": "collect_list",
          "list": "order_list",
          "item": "order_item",
          "fields": {
            "store": "order_item_store",
            "menu": "order_item_menu",
            "date": "order_item_date",
            "status": "order_item_status"
          },
          "until": {
            "count": "{limit}"
          },
          "limit": "{limit}",
          "max_scrolls": 5,
          "bind": "orders"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$orders"
          ],
          "present": "table"
        }
      ]
    }
  ]
}

