          "item": "friend_result_item",
          "match": {
            "field": "friend_item_name",
            "op": "contains",
            "value": "{recipient}"
          },
          "on_multiple": "ask_user",
          "on_none": "abort",
          "bind": "friend"
        },
        {
          "id": "open_friend",
          "op": "tap",
          "target": "$friend"
        },
        {
          "id": "open_chat",
          "op": "if_visible",
          "target": "open_chat_button",
          "then": [
            {
              "id": "tap_open_chat",
              "op": "tap",
              "target": "open_chat_button"
            }
          ]
        },
        {
          "id": "wait_chat",
          "op": "wait_for",
          "target": "chat_input",
          "timeout_ms": 5000
        },
        {
          "id": "read_room",
          "op": "read_text",
          "target": "chat_header_title",
          "bind": "room_name"
        },
        {
          "id": "type_msg",
          "op": "input_text",
          "target": "chat_input",
          "value": "{message}"
        },
        {
          "id": "confirm",
          "op": "confirm_with_user",
          "summary": {
            "ko": "{room_name}에게 아래 메시지를 보냅니다.",
            "en": "Send this message to {room_name}?",
            "ja": "{room_name}に次のメッセージを送信します。",
            "zh-TW": "將傳送以下訊息給{room_name}。"
          },
          "show": [
            "$room_name",
            "{message}"
          ]
        },
        {
          "id": "send",
          "op": "tap",
          "target": "send_button"
        },
        {
