      "summary_ko": "인스타그램의 검색 탭에서 {account}를 검색해 프로필을 열고 최근 게시물 {limit}개를 수집한다.",
      "params": {
        "account": {
          "type": "string",
          "required": true,
          "desc": "계정 이름 또는 @핸들"
        },
        "limit": {
          "type": "int",
          "default": 10,
          "min": 1,
          "max": 50
        }
      },
      "utterances": {
        "ko": [
          "인스타그램에서 {account} 최근 글 보여줘"
        ],
        "en": [
          "Show {account}'s latest posts on Instagram"
        ],
        "ja": [
          "Instagramで{account}の最新投稿見せて"
        ],
        "zh-TW": [
          "看{account}在Instagram的最新貼文"
        ]
      },
      "script_ko": {
        "ko": [
          "1. 인스타그램 앱 실행 (첫 화면으로 초기화)",
          "2. '검색' 탭 선택",
          "3. 입력창 누르기",
          "4. 입력창에 {account} 입력",
          "5. 키보드 'search' 실행",
          "6. 목록에서 [이름]에 '{account}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $account",
          "7. 선택된 항목($account) 누르기",
          "8. 목록을 아래로 스크롤하며 [text, time] 수집 — {limit}개 모이면 멈춤 → $posts",
          "9. 종료 → 결과 $posts (summary)"
        ],
        "en": [
          "1. 인스타그램 앱 실행 (첫 화면으로 초기화)",
          "2. 'Search' 탭 선택",
          "3. 입력창 누르기",
          "4. 입력창에 {account} 입력",
          "5. 키보드 'search' 실행",
          "6. 목록에서 [이름]에 '{account}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $account",
          "7. 선택된 항목($account) 누르기",
          "8. 목록을 아래로 스크롤하며 [text, time] 수집 — {limit}개 모이면 멈춤 → $posts",
          "9. 종료 → 결과 $posts (summary)"
        ],
        "ja": [
          "1. 인스타그램 앱 실행 (첫 화면으로 초기화)",
          "2. '検索' 탭 선택",
          "3. 입력창 누르기",
          "4. 입력창에 {account} 입력",
          "5. 키보드 'search' 실행",
          "6. 목록에서 [이름]에 '{account}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $account",
          "7. 선택된 항목($account) 누르기",
          "8. 목록을 아래로 스크롤하며 [text, time] 수집 — {limit}개 모이면 멈춤 → $posts",
          "9. 종료 → 결과 $posts (summary)"
        ],
        "zh-TW": [
          "1. 인스타그램 앱 실행 (첫 화면으로 초기화)",
          "2. '搜尋' 탭 선택",
          "3. 입력창 누르기",
          "4. 입력창에 {account} 입력",
          "5. 키보드 'search' 실행",
          "6. 목록에서 [이름]에 '{account}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $account",
          "7. 선택된 항목($account) 누르기",
          "8. 목록을 아래로 스크롤하며 [text, time] 수집 — {limit}개 모이면 멈춤 → $posts",
          "9. 종료 → 결과 $posts (summary)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_search",
          "op": "tap",
          "target": "tab_search"
        },
        {
          "id": "focus_search",
          "op": "tap",
          "target": "search_input"
        },
        {
          "id": "type_account",
          "op": "input_text",
          "target": "search_input",
          "value": "{account}"
        },
        {
          "id": "submit",
          "op": "press_ime",
          "action": "search"
        },
        {
          "id": "pick_account",
          "op": "find_in_list",
          "list": "account_result_list",
          "item": "account_result_item",
          "match": {
            "field": "account_result_name",
            "op": "contains",
            "value": "{account}"
          },
          "on_multiple": "ask_user",
          "on_none": "abort",
          "bind": "account"
        },
        {
          "id": "open_account",
          "op": "tap",
          "target": "$account"
        },
        {
          "id": "collect_posts",
          "op": "collect_list",
          "list": "profile_post_list",
          "item": "profile_post_item",
          "fields": {
            "text": "profile_post_text",
            "time": "profile_post_time"
          },
          "until": {
            "count": "{limit}"
          },
          "limit": "{limit}",
          "max_scrolls": 10,
          "bind": "posts"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$posts"
          ],
          "present": "summary"
        }
      ]
    }
  ]
}

