            "sender": "message_sender",
            "text": "message_text",
            "time": "message_time"
          },
          "date_separator": "message_date_separator",
          "until": {
            "field": "time",
            "older_than": "{hours}h"
          },
          "limit": "{limit}",
          "max_scrolls": 20,
          "bind": "messages"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$room_name",
            "$messages"
          ],
          "present": "summary"
        }
      ]
    },
    {
      "id": "msg.reply_chat",
      "version": 1,
      "risk": "R2",
      "computed_commit": "R2",
      "trigger": "user_command",
      "side_effects": [
        "read_receipt"
      ],
      "explicit_target": true,
      "title": {
        "ko": "대화방에 답장하기",
        "en": "Reply in a chat",
        "ja": "トークに返信する",
        "zh-TW": "在聊天室回覆"
      },
      "summary_ko": "카카오톡의 대화 탭에서 {chat_name} 대화방을 검색해 열고 {message}를 입력한 뒤, 사용자 확인 후 전송한다(그룹방에도 사용 가능).",
      "params": {
        "chat_name": {
          "type": "string",
          "required": true,
          "desc": "대화방 이름(친구/그룹)"
        },
        "message": {
          "type": "text",
          "required": true,
          "max_len": 1000
        }
      },
      "utterances": {
        "ko": [
          "카카오톡 {chat_name}방에 \"{message}\"라고 답장해줘"
        ]
      },
      "script_ko": {
        "ko": [
          "1. 카카오톡 앱 실행 (첫 화면으로 초기화)",
          "2. '채팅' 탭 선택",
          "3. '검색' 버튼 누르기",
          "4. 입력창에 {chat_name} 입력",
          "5. 목록에서 [이름]에 '{chat_name}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $chat",
          "6. 선택된 항목($chat) 누르기",
          "7. 목록 표시 대기 (최대 5초)",
          "8. 상단 제목 읽기 → $room_name",
          "9. 입력창에 {message} 입력",
          "10. [사용자 확인] \"{room_name}에 아래 메시지를 보냅니다.\" — 표시: $room_name, {message} / 취소하면 중단",
          "11. '전송' 버튼 누르기 ⟵ 커밋(R2)",
          "12. '{message}' 표시 확인",
          "13. 종료 → 결과 $room_name (none)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_chats",
          "op": "tap",
          "target": "tab_chats"
        },
        {
          "id": "open_chat_search",
          "op": "tap",
          "target": "chat_search"
        },
        {
          "id": "type_chat_name",
          "op": "input_text",
          "target": "search_input",
          "value": "{chat_name}"
        },
        {
          "id": "pick_chat",
          "op": "find_in_list",
          "list": "chat_search_result_list",
          "item": "chat_search_result_item",
          "match": {
            "field": "chat_search_result_name",
            "op": "contains",
            "value": "{chat_name}"
          },
          "on_multiple": "ask_user",
          "on_none": "abort",
          "bind": "chat"
        },
        {
          "id": "open_chat_room",
          "op": "tap",
          "target": "$chat"
        },
        {
          "id": "wait_chat",
          "op": "wait_for",
          "target": "message_list",
          "timeout_ms": 5000
        },
        {
          "id": "read_room",
          "op": "read_text",
          "target": "chat_header_title",
          "bind": "room_name"
        },
        {
          "id": "type_msg",
          "op": "input_text",
          "target": "chat_input",
          "value": "{message}"
        },
        {
          "id": "confirm",
          "op": "confirm_with_user",
          "summary": {
            "ko": "{room_name}에 아래 메시지를 보냅니다.",
            "en": "Send this message to {room_name}?",
            "ja": "{room_name}に次のメッセージを送信します。",
            "zh-TW": "將傳送以下訊息到{room_name}。"
          },
          "show": [
            "$room_name",
            "{message}"
          ]
        },
        {
          "id": "send",
          "op": "tap",
          "target": "send_button"
        },
        {
          "id": "verify",
          "op": "assert_visible",
          "text": "{message}",
          "within": "message_list"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$room_name"
          ],
          "present": "none"
        }
      ]
    },
    {
      "id": "msg.voice_call",
      "version": 1,
      "risk": "R2",
      "computed_commit": "R2",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "친구에게 음성통화 걸기",
        "en": "Voice call a friend",
        "ja": "友だちに音声通話をかける",
        "zh-TW": "撥語音通話給好友"
      },
      "summary_ko": "카카오톡에서 친구 탭을 선택하고 {recipient}를 찾아 프로필을 연 뒤, 사용자 확인 후 음성통화 버튼을 누른다.",
      "params": {
        "recipient": {
          "type": "contact_name",
          "required": true,
          "desc": "대화 상대 표시 이름"
        }
      },
      "utterances": {
        "ko": [
          "카카오톡에서 {recipient}에게 전화 걸어줘"
        ]
      },
      "script_ko": {
        "ko": [
          "1. 카카오톡 앱 실행 (첫 화면으로 초기화)",
          "2. '친구' 탭 선택",
          "3. '검색' 버튼 누르기",
          "4. 입력창에 {recipient} 입력",
          "5. 목록에서 [이름]에 '{recipient}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $friend",
          "6. 선택된 항목($friend) 누르기",
          "7. [사용자 확인] \"{friend.name}에게 음성통화를 겁니다.\" — 표시: $friend.name / 취소하면 중단",
          "8. '통화하기' 버튼 누르기",
          "9. '보이스톡' 버튼 누르기 ⟵ 커밋(R2)",
          "10. 종료 → 결과 $friend.name (none)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_friends",
          "op": "tap",
          "target": "tab_friends"
        },
        {
          "id": "open_search",
          "op": "tap",
          "target": "friends_search"
        },
        {
          "id": "type_name",
          "op": "input_text",
          "target": "search_input",
          "value": "{recipient}"
        },
        {
          "id": "pick_friend",
          "op": "find_in_list",
          "list": "friend_result_list",
          "item": "friend_result_item",
          "match": {
            "field": "friend_item_name",
            "op": "contains",
            "value": "{recipient}"
          },
          "on_multiple": "ask_user",
          "on_none": "abort",
          "bind": "friend"
        },
        {
          "id": "open_friend",
          "op": "tap",
          "target": "$friend"
        },
        {
          "id": "confirm",
          "op": "confirm_with_user",
          "summary": {
            "ko": "{friend.name}에게 음성통화를 겁니다.",
            "en": "Call {friend.name}?",
            "ja": "{friend.name}に音声通話をかけます。",
            "zh-TW": "將撥打語音通話給{friend.name}。"
          },
          "show": [
            "$friend.name"
          ]
        },
        {
          "id": "open_call_menu",
          "op": "tap",
          "target": "profile_call_menu"
        },
        {
          "id": "call",
          "op": "tap",
          "target": "profile_voice_call"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$friend.name"
          ],
          "present": "none"
        }
      ]
    },
    {
      "id": "msg.share_to_chat",
      "version": 1,
      "risk": "R2",
      "computed_commit": "R2",
      "trigger": "internal",
      "side_effects": [],
      "explicit_target": true,
      "title": {
        "ko": "정기 조사 결과를 대화방에 보내기",
        "en": "Send research results to a chat",
        "ja": "定期調査の結果をトークに送る",
        "zh-TW": "將定期調查結果傳到聊天室"
      },
      "summary_ko": "구름이 정기 조사 결과(요약 글 + PDF)를 그 앱의 공유 화면으로 넘기고, 공유 대상 목록에서 {chat_name} 대화방을 찾아 고른 뒤 사용자 확인(또는 그 보내기 설정의 동의) 후 보낸다.",
      "params": {
        "chat_name": {
          "type": "string",
          "required": true,
          "desc": "대화방 이름(정기 조사 보내기 설정에서 고른 것)"
        }
      },
      "utterances": {},
      "script_ko": {},
      "steps": [
        {
          "id": "open_share",
          "op": "open_share"
        },
        {
          "id": "wait_list",
          "op": "wait_for",
          "target": "share_list",
          "timeout_ms": 10000
        },
        {
          "id": "search",
          "op": "if_visible",
          "target": "share_search_input",
          "then": [
            {
              "id": "type_name",
              "op": "input_text",
              "target": "share_search_input",
              "value": "{chat_name}"
            }
          ],
          "else": [
            {
              "id": "search_open",
              "op": "if_visible",
              "target": "share_search",
              "then": [
                {
                  "id": "tap_search",
                  "op": "tap",
                  "target": "share_search"
                },
                {
                  "id": "type_name2",
                  "op": "input_text",
                  "target": "share_search_input",
                  "value": "{chat_name}"
                }
              ]
            }
          ]
        },
        {
          "id": "pick_chat",
          "op": "find_in_list",
          "list": "share_list",
          "item": "share_item",
          "match": {
            "field": "share_item_name",
            "op": "equals",
            "value": "{chat_name}"
          },
          "on_multiple": "ask_user",
          "on_none": "abort",
          "bind": "chat"
        },
        {
          "id": "select_chat",
          "op": "tap",
          "target": "$chat"
        },
        {
          "id": "confirm",
          "op": "confirm_with_user",
          "summary": {
            "ko": "‘{chat_name}’ 대화방에 정기 조사 결과(요약과 PDF)를 보냅니다.",
            "en": "Send the research results (summary and PDF) to the chat ‘{chat_name}’?",
            "ja": "「{chat_name}」に定期調査の結果(要約とPDF)を送信します。",
            "zh-TW": "將把定期調查結果(摘要與PDF)傳送到「{chat_name}」。"
          },
          "show": [
            "$chat.name"
          ]
        },
        {
          "id": "send",
          "op": "tap",
          "target": "share_send_button"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$chat.name"
          ],
          "present": "none"
        }
      ]
    }
  ]
}

