  "scenarios": [
    {
      "id": "travel.search",
      "version": 1,
      "risk": "R0",
      "computed_commit": "R0",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "숙소/여행상품 검색",
        "en": "Search stays",
        "ja": "宿・プランを検索",
        "zh-TW": "搜尋住宿/行程"
      },
      "summary_ko": "케이케이데이에서 목적지 {destination}, {checkin}~{checkout}, 성인 {adults}명으로 검색하고 광고를 제외한 상위 {limit}개의 이름, 가격, 평점을 읽는다.",
      "params": {
        "destination": {
          "type": "string",
          "required": true,
          "desc": "목적지/숙소/상품 이름"
        },
        "checkin": {
          "type": "date",
          "required": true
        },
        "checkout": {
          "type": "date",
          "required": true
        },
        "adults": {
          "type": "int",
          "default": 2,
          "min": 1,
          "max": 16
        },
        "limit": {
          "type": "int",
          "default": 5,
          "min": 1,
          "max": 20
        }
      },
      "utterances": {
        "ko": [
          "케이케이데이에서 {destination} {checkin}부터 {checkout}까지 {adults}명 숙소 찾아줘"
        ],
        "zh-TW": [
          "用KKday找{destination}{checkin}到{checkout}{adults}人的住宿"
        ]
      },
      "script_ko": {
        "zh-TW": [
          "1. 케이케이데이 앱 실행 (첫 화면으로 초기화)",
          "2. '搜尋目的地、體驗' 버튼 누르기",
          "3. 입력창에 {destination} 입력",
          "4. 목록에서 [이름]에 '{destination}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $place",
          "5. 선택된 항목($place) 누르기",
          "6. '{checkin|day}'가 보이면 (그대로 진행)",
          "   → 아니라면:",
          "    6.1. '日期' 버튼 누르기",
          "7. '{checkin|day}' 누르기",
          "8. '{checkout|day}' 누르기",
          "9. '套用'가 보이면",
          "   → 그렇다면:",
          "    9.1. '套用' 버튼 누르기",
          "10. '人數'가 보이면",
          "   → 그렇다면:",
          "    10.1. '人數' 버튼 누르기",
          "    10.2. [성인 인원 수] 값을 {adults}로 맞추기 (+/− 버튼을 반복해서 누름)",
          "    10.3. '套用'가 보이면",
          "       → 그렇다면:",
          "        10.3.1. '套用' 버튼 누르기",
          "11. '搜尋'가 보이면",
          "   → 그렇다면:",
          "    11.1. '搜尋' 버튼 누르기",
          "12. 목록 표시 대기 (최대 15초)",
          "13. 목록을 아래로 스크롤하며 [name, price, rating, ad] 수집 — {limit}개 모이면 멈춤, 광고 제외 → $results",
          "14. 종료 → 결과 $results (table)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "open_destination",
          "op": "tap",
          "target": "destination_entry"
        },
        {
          "id": "type_destination",
          "op": "input_text",
          "target": "destination_input",
          "value": "{destination}"
        },
        {
          "id": "pick_suggestion",
          "op": "find_in_list",
          "list": "suggestion_list",
          "item": "suggestion_item",
          "match": {
            "field": "suggestion_name",
            "op": "contains",
            "value": "{destination}"
          },
          "on_multiple": "ask_user",
          "on_none": "abort",
          "bind": "place"
        },
        {
          "id": "tap_suggestion",
          "op": "tap",
          "target": "$place"
        },
        {
          "id": "open_dates",
          "op": "if_visible",
          "target": "checkin_cell",
          "else": [
            {
              "id": "tap_dates",
              "op": "tap",
              "target": "date_entry"
            }
          ]
        },
        {
          "id": "tap_checkin",
          "op": "tap",
          "target": "checkin_cell"
        },
        {
          "id": "tap_checkout",
          "op": "tap",
          "target": "checkout_cell"
        },
        {
          "id": "apply_dates",
          "op": "if_visible",
          "target": "date_apply_button",
          "then": [
            {
              "id": "tap_apply",
              "op": "tap",
              "target": "date_apply_button"
            }
          ]
        },
        {
          "id": "open_guests",
          "op": "if_visible",
          "target": "guests_entry",
          "then": [
            {
              "id": "tap_guests",
              "op": "tap",
              "target": "guests_entry"
            },
            {
              "id": "set_adults",
              "op": "set_stepper",
              "value_anchor": "adults_value",
              "plus": "adults_plus",
              "minus": "adults_minus",
              "value": "{adults}",
              "max_taps": 16
            },
            {
              "id": "apply_guests",
              "op": "if_visible",
              "target": "date_apply_button",
              "then": [
                {
                  "id": "tap_apply_guests",
                  "op": "tap",
                  "target": "date_apply_button"
                }
              ]
            }
          ]
        },
        {
          "id": "search",
          "op": "if_visible",
          "target": "search_button",
          "then": [
            {
              "id": "tap_search",
              "op": "tap",
              "target": "search_button"
            }
          ]
        },
        {
          "id": "wait_results",
          "op": "wait_for",
          "target": "result_list",
          "timeout_ms": 15000
        },
        {
          "id": "collect_results",
          "op": "collect_list",
          "list": "result_list",
          "item": "result_item",
          "fields": {
            "name": "result_name",
            "price": "result_price",
            "rating": "result_rating",
            "ad": "result_ad_badge"
          },
          "filter": {
            "exclude_if": "ad"
          },
          "until": {
            "count": "{limit}"
          },
          "limit": "{limit}",
          "max_scrolls": 6,
          "bind": "results"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$results"
          ],
          "present": "table"
        }
      ]
    },
    {
