        {
          "id": "tap_checkin",
          "op": "tap",
          "target": "checkin_cell"
        },
        {
          "id": "tap_checkout",
          "op": "tap",
          "target": "checkout_cell"
        },
        {
          "id": "apply_dates",
          "op": "if_visible",
          "target": "date_apply_button",
          "then": [
            {
              "id": "tap_apply",
              "op": "tap",
              "target": "date_apply_button"
            }
          ]
        },
        {
          "id": "open_guests",
          "op": "if_visible",
          "target": "guests_entry",
          "then": [
            {
              "id": "tap_guests",
              "op": "tap",
