            }
          ]
        },
        {
          "id": "search",
          "op": "if_visible",
          "target": "search_button",
          "then": [
            {
              "id": "tap_search",
              "op": "tap",
              "target": "search_button"
            }
          ]
        },
        {
          "id": "wait_results",
          "op": "wait_for",
          "target": "result_list",
          "timeout_ms": 15000
        },
        {
          "id": "collect_results",
          "op": "collect_list",
          "list": "result_list",
          "item": "result_item",
          "fields": {
            "name": "result_name",
            "price": "result_price",
            "rating": "result_rating",
            "ad": "result_ad_badge"
          },
          "filter": {
            "exclude_if": "ad"
          },
          "until": {
            "count": "{limit}"
          },
          "limit": "{limit}",
          "max_scrolls": 6,
          "bind": "results"
        },
        {
          "id": "choose_property",
          "op": "choose_by_user",
          "from": "$results",
          "display": [
            "name",
            "price",
            "rating"
          ],
          "bind": "property"
        },
        {
          "id": "open_property",
          "op": "tap",
          "target": "$property"
        },
        {
          "id": "open_rooms",
          "op": "tap",
          "target": "select_room_entry"
        },
        {
          "id": "collect_rooms",
          "op": "collect_list",
          "list": "room_list",
          "item": "room_item",
          "fields": {
            "name": "room_name",
            "price": "room_price"
          },
          "until": {
            "count": 10
          },
          "limit": 10,
          "max_scrolls": 5,
          "bind": "rooms"
        },
        {
          "id": "choose_room",
          "op": "choose_by_user",
          "from": "$rooms",
          "display": [
