  "scenarios": [
    {
      "id": "msg.send_text",
      "version": 1,
      "risk": "R2",
      "computed_commit": "R2",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "친구에게 메시지 보내기",
        "en": "Send a message to a friend",
        "ja": "友だちにメッセージを送る",
        "zh-TW": "傳訊息給好友"
      },
      "summary_ko": "라인에서 친구 탭을 선택하고 {recipient}를 찾아 대화방을 연 뒤 {message}를 입력하고, 사용자 확인 후 전송한다.",
      "params": {
        "recipient": {
          "type": "contact_name",
          "required": true,
          "desc": "대화 상대 표시 이름"
        },
        "message": {
          "type": "text",
          "required": true,
          "max_len": 1000
        }
      },
      "utterances": {
        "ko": [
          "라인에서 {recipient}에게 \"{message}\" 보내줘",
          "라인에서 {recipient}한테 {message}라고 메시지 보내"
        ],
        "ja": [
          "LINEで{recipient}に「{message}」って送って",
          "{recipient}にLINEで「{message}」とメッセージして"
        ],
        "zh-TW": [
          "用LINE傳「{message}」給{recipient}",
          "在LINE跟{recipient}說「{message}」"
        ]
      },
      "script_ko": {
        "ja": [
          "1. 라인 앱 실행 (첫 화면으로 초기화)",
          "2. 'ホーム' 탭 선택",
          "3. '検索' 버튼 누르기",
          "4. 입력창에 {recipient} 입력",
          "5. 목록에서 [이름]에 '{recipient}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $friend",
          "6. 선택된 항목($friend) 누르기",
          "7. 'トーク'가 보이면",
          "   → 그렇다면:",
          "    7.1. 'トーク' 버튼 누르기",
          "8. 입력창 표시 대기 (최대 5초)",
          "9. 상단 제목 읽기 → $room_name",
          "10. 입력창에 {message} 입력",
          "11. [사용자 확인] \"{room_name}에게 아래 메시지를 보냅니다.\" — 표시: $room_name, {message} / 취소하면 중단",
          "12. '送信' 버튼 누르기 ⟵ 커밋(R2)",
          "13. '{message}' 표시 확인",
          "14. 종료 → 결과 $room_name (none)"
        ],
        "zh-TW": [
          "1. 라인 앱 실행 (첫 화면으로 초기화)",
          "2. '主頁' 탭 선택",
          "3. '搜尋' 버튼 누르기",
          "4. 입력창에 {recipient} 입력",
          "5. 목록에서 [이름]에 '{recipient}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $friend",
          "6. 선택된 항목($friend) 누르기",
          "7. '聊天'가 보이면",
          "   → 그렇다면:",
          "    7.1. '聊天' 버튼 누르기",
          "8. 입력창 표시 대기 (최대 5초)",
          "9. 상단 제목 읽기 → $room_name",
          "10. 입력창에 {message} 입력",
          "11. [사용자 확인] \"{room_name}에게 아래 메시지를 보냅니다.\" — 표시: $room_name, {message} / 취소하면 중단",
          "12. '傳送' 버튼 누르기 ⟵ 커밋(R2)",
          "13. '{message}' 표시 확인",
          "14. 종료 → 결과 $room_name (none)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_friends",
          "op": "tap",
          "target": "tab_friends"
        },
        {
          "id": "open_search",
          "op": "tap",
          "target": "friends_search"
        },
        {
          "id": "type_name",
          "op": "input_text",
          "target": "search_input",
          "value": "{recipient}"
        },
        {
          "id": "pick_friend",
          "op": "find_in_list",
          "list": "friend_result_list",
          "item": "friend_result_item",
          "match": {
            "field": "friend_item_name",
            "op": "contains",
            "value": "{recipient}"
          },
          "on_multiple": "ask_user",
          "on_none": "abort",
          "bind": "friend"
        },
        {
          "id": "open_friend",
          "op": "tap",
          "target": "$friend"
        },
        {
          "id": "open_chat",
          "op": "if_visible",
          "target": "open_chat_button",
          "then": [
            {
              "id": "tap_open_chat",
              "op": "tap",
              "target": "open_chat_button"
            }
          ]
        },
        {
          "id": "wait_chat",
          "op": "wait_for",
          "target": "chat_input",
          "timeout_ms": 5000
        },
        {
          "id": "read_room",
          "op": "read_text",
          "target": "chat_header_title",
          "bind": "room_name"
        },
        {
          "id": "type_msg",
          "op": "input_text",
          "target": "chat_input",
          "value": "{message}"
        },
        {
          "id": "confirm",
          "op": "confirm_with_user",
          "summary": {
            "ko": "{room_name}에게 아래 메시지를 보냅니다.",
            "en": "Send this message to {room_name}?",
            "ja": "{room_name}に次のメッセージを送信します。",
            "zh-TW": "將傳送以下訊息給{room_name}。"
          },
          "show": [
            "$room_name",
            "{message}"
          ]
        },
        {
          "id": "send",
          "op": "tap",
          "target": "send_button"
        },
        {
          "id": "verify",
          "op": "assert_visible",
          "text": "{message}",
          "within": "message_list"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$room_name"
          ],
          "present": "none"
        }
      ]
    },
