    {
      "id": "msg.voice_call",
      "version": 1,
      "risk": "R2",
      "computed_commit": "R2",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "친구에게 음성통화 걸기",
        "en": "Voice call a friend",
        "ja": "友だちに音声通話をかける",
        "zh-TW": "撥語音通話給好友"
      },
      "summary_ko": "라인에서 친구 탭을 선택하고 {recipient}를 찾아 프로필을 연 뒤, 사용자 확인 후 음성통화 버튼을 누른다.",
      "params": {
        "recipient": {
          "type": "contact_name",
          "required": true,
          "desc": "대화 상대 표시 이름"
        }
      },
      "utterances": {
        "ko": [
          "라인에서 {recipient}에게 전화 걸어줘"
        ],
        "ja": [
          "LINEで{recipient}に電話して"
        ],
        "zh-TW": [
          "用LINE打給{recipient}"
        ]
      },
      "script_ko": {
        "ja": [
          "1. 라인 앱 실행 (첫 화면으로 초기화)",
          "2. 'ホーム' 탭 선택",
          "3. '検索' 버튼 누르기",
          "4. 입력창에 {recipient} 입력",
          "5. 목록에서 [이름]에 '{recipient}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $friend",
          "6. 선택된 항목($friend) 누르기",
          "7. [사용자 확인] \"{friend.name}에게 음성통화를 겁니다.\" — 표시: $friend.name / 취소하면 중단",
          "8. '音声通話' 버튼 누르기 ⟵ 커밋(R2)",
          "9. 종료 → 결과 $friend.name (none)"
        ],
        "zh-TW": [
          "1. 라인 앱 실행 (첫 화면으로 초기화)",
          "2. '主頁' 탭 선택",
          "3. '搜尋' 버튼 누르기",
          "4. 입력창에 {recipient} 입력",
          "5. 목록에서 [이름]에 '{recipient}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $friend",
          "6. 선택된 항목($friend) 누르기",
          "7. [사용자 확인] \"{friend.name}에게 음성통화를 겁니다.\" — 표시: $friend.name / 취소하면 중단",
          "8. '語音通話' 버튼 누르기 ⟵ 커밋(R2)",
          "9. 종료 → 결과 $friend.name (none)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_friends",
