                {
                  "id": "tap_search",
                  "op": "tap",
                  "target": "share_search"
                },
                {
                  "id": "type_name2",
                  "op": "input_text",
                  "target": "share_search_input",
                  "value": "{chat_name}"
                }
              ]
            }
          ]
        },
        {
          "id": "pick_chat",
          "op": "find_in_list",
          "list": "share_list",
          "item": "share_item",
          "match": {
            "field": "share_item_name",
            "op": "equals",
            "value": "{chat_name}"
          },
          "on_multiple": "ask_user",
          "on_none": "abort",
          "bind": "chat"
        },
        {
          "id": "select_chat",
          "op": "tap",
          "target": "$chat"
        },
        {
          "id": "confirm",
          "op": "confirm_with_user",
          "summary": {
            "ko": "‘{chat_name}’ 대화방에 정기 조사 결과(요약과 PDF)를 보냅니다.",
            "en": "Send the research results (summary and PDF) to the chat ‘{chat_name}’?",
            "ja": "「{chat_name}」に定期調査の結果(要約とPDF)を送信します。",
            "zh-TW": "將把定期調查結果(摘要與PDF)傳送到「{chat_name}」。"
