    },
    {
      "id": "msg.reply_chat",
      "version": 1,
      "risk": "R2",
      "computed_commit": "R2",
      "trigger": "user_command",
      "side_effects": [
        "read_receipt"
      ],
      "explicit_target": true,
      "title": {
        "ko": "대화방에 답장하기",
        "en": "Reply in a chat",
        "ja": "トークに返信する",
        "zh-TW": "在聊天室回覆"
      },
      "summary_ko": "메신저의 대화 탭에서 {chat_name} 대화방을 검색해 열고 {message}를 입력한 뒤, 사용자 확인 후 전송한다(그룹방에도 사용 가능).",
      "params": {
        "chat_name": {
          "type": "string",
          "required": true,
          "desc": "대화방 이름(친구/그룹)"
        },
        "message": {
          "type": "text",
          "required": true,
          "max_len": 1000
        }
      },
      "utterances": {
        "ko": [
          "메신저 {chat_name}방에 \"{message}\"라고 답장해줘"
        ],
        "en": [
          "Reply \"{message}\" in the {chat_name} chat on Messenger"
        ],
        "zh-TW": [
          "在Messenger的{chat_name}回覆「{message}」"
        ]
      },
