        "query": {
          "type": "string",
          "required": true,
          "desc": "검색어"
        },
        "limit": {
          "type": "int",
          "default": 5,
          "min": 1,
          "max": 20
        }
      },
      "utterances": {
        "ko": [
          "네이버플러스 스토어에서 {query} 검색해줘",
          "네이버플러스 스토어에 {query} 얼마야?"
        ]
      },
      "script_ko": {
        "ko": [
          "1. 네이버플러스 스토어 앱 실행 (첫 화면으로 초기화)",
          "2. '검색' 버튼 누르기",
          "3. 입력창에 {query} 입력",
          "4. 키보드 'search' 실행",
          "5. 목록 표시 대기 (최대 8초)",
          "6. 목록을 아래로 스크롤하며 [title, price, rating, ad] 수집 — {limit}개 모이면 멈춤, 광고 제외 → $results",
          "7. 종료 → 결과 $results (table)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "open_search",
          "op": "tap",
          "target": "search_entry"
        },
        {
          "id": "type_query",
          "op": "input_text",
          "target": "search_input",
          "value": "{query}"
        },
        {
          "id": "submit",
          "op": "press_ime",
          "action": "search"
        },
        {
          "id": "wait_results",
          "op": "wait_for",
          "target": "result_list",
          "timeout_ms": 8000
        },
        {
          "id": "collect_results",
          "op": "collect_list",
          "list": "result_list",
          "item": "result_item",
          "fields": {
            "title": "result_title",
            "price": "result_price",
            "rating": "result_rating",
            "ad": "result_ad_badge"
          },
          "filter": {
            "exclude_if": "ad"
          },
          "until": {
            "count": "{limit}"
          },
          "limit": "{limit}",
          "max_scrolls": 6,
          "bind": "results"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$results"
          ],
          "present": "table"
        }
      ]
    },
