          "7. [사용자 확인] \"{order.title} 주문의 취소/반품 화면으로 이동합니다.\" — 표시: $order.title / 취소하면 중단",
          "8. 선택된 항목($order) 누르기",
          "9. '취소/반품' 버튼 누르기",
          "10. [사용자에게 인계] \"사유를 선택하고 신청 버튼을 직접 눌러 주세요.\" — 사용자가 '신청하기'를 직접 누름, '신청 완료' 확인까지 대기",
          "11. 종료 → 결과 $order.title (none)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_my",
          "op": "tap",
          "target": "my_page_entry"
        },
        {
          "id": "go_orders",
          "op": "tap",
          "target": "orders_entry"
        },
        {
          "id": "wait_orders",
          "op": "wait_for",
          "target": "order_list",
          "timeout_ms": 8000
        },
        {
          "id": "collect_orders",
          "op": "collect_list",
          "list": "order_list",
          "item": "order_item",
          "fields": {
            "title": "order_item_title",
            "date": "order_item_date",
            "status": "order_item_status"
          },
          "until": {
            "count": "{limit}"
          },
          "limit": "{limit}",
          "max_scrolls": 6,
          "bind": "orders"
        },
        {
          "id": "choose_order",
          "op": "choose_by_user",
          "from": "$orders",
          "display": [
            "title",
            "date",
            "status"
          ],
          "bind": "order"
        },
        {
          "id": "confirm",
          "op": "confirm_with_user",
          "summary": {
            "ko": "{order.title} 주문의 취소/반품 화면으로 이동합니다.",
            "en": "Open cancel/return for {order.title}?",
            "ja": "{order.title}のキャンセル・返品画面に進みます。",
            "zh-TW": "將開啟{order.title}的取消/退貨。"
          },
          "show": [
            "$order.title"
          ]
        },
        {
          "id": "open_order",
          "op": "tap",
          "target": "$order"
        },
        {
          "id": "tap_cancel",
          "op": "tap",
          "target": "cancel_return_button"
        },
        {
          "id": "handoff",
          "op": "handoff_to_user",
          "instruction": {
            "ko": "사유를 선택하고 신청 버튼을 직접 눌러 주세요.",
            "en": "Choose a reason and submit it yourself.",
            "ja": "理由を選んで申し込みボタンを押してください。",
            "zh-TW": "請選擇原因並自行送出。"
          },
          "commit_anchor": "cancel_submit_button",
          "success_marker": "cancel_done_marker",
          "timeout_ms": 600000
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$order.title"
          ],
          "present": "none"
        }
      ]
    }
  ]
}

