      "id": "travel.book",
      "version": 1,
      "risk": "R3",
      "computed_commit": "R3",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "숙소/상품 예약하기",
        "en": "Book a stay",
        "ja": "宿を予約",
        "zh-TW": "預訂住宿/行程"
      },
      "summary_ko": "라쿠텐 트래블에서 {destination}을 검색해 사용자가 고른 숙소와 객실(상품)로 예약서까지 이동하고, 총액과 취소 규정을 보여 준 뒤 결제 버튼은 사용자가 직접 누르게 한다.",
      "params": {
        "destination": {
          "type": "string",
          "required": true,
          "desc": "목적지/숙소/상품 이름"
        },
        "checkin": {
          "type": "date",
          "required": true
        },
        "checkout": {
          "type": "date",
          "required": true
        },
        "adults": {
          "type": "int",
          "default": 2,
          "min": 1,
          "max": 16
        },
        "limit": {
          "type": "int",
          "default": 5,
          "min": 1,
          "max": 20
        }
      },
      "utterances": {
        "ko": [
          "라쿠텐 트래블에서 {destination} {checkin}~{checkout} 숙소 예약 진행해줘"
        ],
        "ja": [
          "楽天トラベルで{destination}の宿を{checkin}から{checkout}で予約して"
        ]
      },
      "script_ko": {
        "ja": [
          "1. 라쿠텐 트래블 앱 실행 (첫 화면으로 초기화)",
          "2. 'エリア・宿名' 버튼 누르기",
          "3. 입력창에 {destination} 입력",
          "4. 목록에서 [이름]에 '{destination}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $place",
          "5. 선택된 항목($place) 누르기",
          "6. '{checkin|day}'가 보이면 (그대로 진행)",
          "   → 아니라면:",
          "    6.1. '日付' 버튼 누르기",
          "7. '{checkin|day}' 누르기",
          "8. '{checkout|day}' 누르기",
          "9. '決定'가 보이면",
          "   → 그렇다면:",
          "    9.1. '決定' 버튼 누르기",
          "10. '人数'가 보이면",
          "   → 그렇다면:",
          "    10.1. '人数' 버튼 누르기",
          "    10.2. [성인 인원 수] 값을 {adults}로 맞추기 (+/− 버튼을 반복해서 누름)",
          "    10.3. '決定'가 보이면",
          "       → 그렇다면:",
          "        10.3.1. '決定' 버튼 누르기",
          "11. '検索'가 보이면",
          "   → 그렇다면:",
          "    11.1. '検索' 버튼 누르기",
          "12. 목록 표시 대기 (최대 15초)",
          "13. 목록을 아래로 스크롤하며 [name, price, rating, ad] 수집 — {limit}개 모이면 멈춤, 광고 제외 → $results",
          "14. [사용자 선택] $results을 보여주고 사용자가 직접 고름 → $property",
          "15. 선택된 항목($property) 누르기",
          "16. 'プラン一覧' 버튼 누르기",
          "17. 목록을 아래로 스크롤하며 [name, price] 수집 — 10개 모이면 멈춤 → $rooms",
          "18. [사용자 선택] $rooms을 보여주고 사용자가 직접 고름 → $room",
          "19. '予約へ進む' 버튼 누르기 ($room 안에서)",
          "20. '予約者情報' 표시 대기 (최대 15초)",
          "21. [합계 금액] 읽기 → $total",
          "22. [취소 규정] 읽기 → $policy",
          "23. [사용자에게 인계] \"{property.name} / {room.name}, {checkin}~{checkout}, 총액 {total}. 취소 규정: {policy}. 확인 후 결제 버튼을 직접 눌러 주세요.\" — 사용자가 '予約を確定する'를 직접 누름, '予約が完了しました' 확인까지 대기",
          "24. 종료 → 결과 $property.name, $room.name, $total (none)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "open_destination",
          "op": "tap",
          "target": "destination_entry"
        },
        {
          "id": "type_destination",
          "op": "input_text",
          "target": "destination_input",
          "value": "{destination}"
        },
        {
          "id": "pick_suggestion",
          "op": "find_in_list",
          "list": "suggestion_list",
          "item": "suggestion_item",
          "match": {
            "field": "suggestion_name",
            "op": "contains",
            "value": "{destination}"
          },
          "on_multiple": "ask_user",
          "on_none": "abort",
          "bind": "place"
        },
        {
          "id": "tap_suggestion",
          "op": "tap",
          "target": "$place"
        },
        {
          "id": "open_dates",
          "op": "if_visible",
          "target": "checkin_cell",
          "else": [
            {
              "id": "tap_dates",
              "op": "tap",
              "target": "date_entry"
            }
          ]
        },
        {
          "id": "tap_checkin",
          "op": "tap",
          "target": "checkin_cell"
        },
        {
          "id": "tap_checkout",
          "op": "tap",
          "target": "checkout_cell"
        },
        {
          "id": "apply_dates",
          "op": "if_visible",
          "target": "date_apply_button",
          "then": [
            {
              "id": "tap_apply",
              "op": "tap",
              "target": "date_apply_button"
            }
          ]
        },
        {
          "id": "open_guests",
          "op": "if_visible",
          "target": "guests_entry",
          "then": [
            {
              "id": "tap_guests",
              "op": "tap",
              "target": "guests_entry"
            },
            {
              "id": "set_adults",
              "op": "set_stepper",
              "value_anchor": "adults_value",
              "plus": "adults_plus",
              "minus": "adults_minus",
              "value": "{adults}",
              "max_taps": 16
            },
            {
              "id": "apply_guests",
              "op": "if_visible",
              "target": "date_apply_button",
              "then": [
                {
                  "id": "tap_apply_guests",
                  "op": "tap",
                  "target": "date_apply_button"
                }
              ]
            }
          ]
        },
        {
          "id": "search",
          "op": "if_visible",
          "target": "search_button",
          "then": [
            {
              "id": "tap_search",
              "op": "tap",
              "target": "search_button"
            }
          ]
        },
        {
          "id": "wait_results",
          "op": "wait_for",
          "target": "result_list",
          "timeout_ms": 15000
        },
        {
          "id": "collect_results",
          "op": "collect_list",
          "list": "result_list",
          "item": "result_item",
          "fields": {
            "name": "result_name",
            "price": "result_price",
            "rating": "result_rating",
            "ad": "result_ad_badge"
          },
          "filter": {
            "exclude_if": "ad"
          },
          "until": {
            "count": "{limit}"
          },
          "limit": "{limit}",
          "max_scrolls": 6,
          "bind": "results"
        },
        {
          "id": "choose_property",
          "op": "choose_by_user",
          "from": "$results",
          "display": [
            "name",
            "price",
            "rating"
          ],
          "bind": "property"
        },
        {
          "id": "open_property",
          "op": "tap",
          "target": "$property"
        },
        {
          "id": "open_rooms",
          "op": "tap",
          "target": "select_room_entry"
        },
        {
          "id": "collect_rooms",
          "op": "collect_list",
          "list": "room_list",
          "item": "room_item",
          "fields": {
            "name": "room_name",
            "price": "room_price"
          },
          "until": {
            "count": 10
          },
          "limit": 10,
          "max_scrolls": 5,
          "bind": "rooms"
        },
        {
          "id": "choose_room",
          "op": "choose_by_user",
          "from": "$rooms",
          "display": [
            "name",
            "price"
          ],
          "bind": "room"
        },
        {
          "id": "reserve_room",
          "op": "tap",
          "target": "room_reserve_button",
          "within": "$room"
        },
        {
          "id": "wait_form",
          "op": "wait_for",
          "target": "booking_form_marker",
          "timeout_ms": 15000
        },
        {
          "id": "read_total",
          "op": "read_text",
          "target": "booking_total",
          "bind": "total"
        },
        {
          "id": "read_policy",
          "op": "read_text",
          "target": "booking_cancel_policy",
          "bind": "policy"
        },
        {
          "id": "handoff_pay",
          "op": "handoff_to_user",
          "instruction": {
            "ko": "{property.name} / {room.name}, {checkin}~{checkout}, 총액 {total}. 취소 규정: {policy}. 확인 후 결제 버튼을 직접 눌러 주세요.",
            "en": "{property.name} / {room.name}, {checkin} to {checkout}, total {total}. Policy: {policy}. Tap pay yourself.",
            "ja": "{property.name}／{room.name}、{checkin}〜{checkout}、合計{total}。キャンセル規定：{policy}。確認して確定してください。",
            "zh-TW": "{property.name}／{room.name}，{checkin}至{checkout}，總額{total}。取消政策：{policy}。請自行付款。"
          },
          "commit_anchor": "pay_button",
          "success_marker": "booking_done_marker",
          "timeout_ms": 900000
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$property.name",
            "$room.name",
            "$total"
          ],
          "present": "none"
        }
      ]
    },
