          "bind": "status"
        },
        {
          "id": "read_eta",
          "op": "read_text",
          "target": "tracking_eta",
          "bind": "eta"
        },
        {
          "id": "read_carrier",
          "op": "read_text",
          "target": "tracking_carrier",
          "bind": "carrier"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$order.title",
            "$status",
            "$eta",
            "$carrier"
          ],
          "present": "summary"
        }
      ]
    },
    {
      "id": "shop.reorder_to_cart",
