    {
      "id": "dine.search_availability",
      "version": 1,
      "risk": "R0",
      "computed_commit": "R0",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "식당 예약 가능 시간 확인",
        "en": "Check restaurant availability",
        "ja": "空席を確認",
        "zh-TW": "查詢可訂位時段"
      },
      "summary_ko": "타베로그에서 {restaurant}를 검색해 식당을 열고 예약하기에서 {date}, {party_size}명을 선택한 뒤 가능한 시간대를 읽는다(예약하지 않음).",
      "params": {
        "restaurant": {
          "type": "string",
          "required": true,
          "desc": "식당 이름"
        },
        "date": {
          "type": "date",
          "required": true
        },
        "party_size": {
          "type": "int",
          "required": true,
          "min": 1,
          "max": 20
        }
      },
      "utterances": {
        "ko": [
          "타베로그에서 {restaurant} {date} {party_size}명 예약 가능한 시간 알려줘"
        ],
        "ja": [
          "食べログで{restaurant}の{date}に{party_size}名で空いてる時間は？"
        ]
      },
      "script_ko": {
        "ja": [
          "1. 타베로그 앱 실행 (첫 화면으로 초기화)",
          "2. '検索' 버튼 누르기",
          "3. 입력창에 {restaurant} 입력",
          "4. 키보드 'search' 실행",
          "5. 목록에서 [이름]에 '{restaurant}'가 포함된 항목 찾기 — 여러 개면 사용자에게 선택 요청, 없으면 중단 → $venue",
          "6. 선택된 항목($venue) 누르기",
          "7. '空席確認・予約する' 버튼 누르기",
          "8. '{date|day}' 누르기",
          "9. '{party_size}名' 버튼 누르기",
          "10. 목록을 아래로 스크롤하며 [time] 수집 — 목록 끝까지 → $slots",
          "11. 종료 → 결과 $venue.name, $slots (table)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "open_search",
          "op": "tap",
          "target": "search_entry"
        },
        {
          "id": "type_name",
          "op": "input_text",
          "target": "search_input",
          "value": "{restaurant}"
        },
        {
          "id": "submit",
          "op": "press_ime",
          "action": "search"
        },
        {
          "id": "pick_venue",
          "op": "find_in_list",
          "list": "venue_list",
          "item": "venue_item",
          "match": {
            "field": "venue_name",
            "op": "contains",
            "value": "{restaurant}"
          },
          "on_multiple": "ask_user",
          "on_none": "abort",
          "bind": "venue"
        },
        {
          "id": "open_venue",
          "op": "tap",
          "target": "$venue"
        },
        {
          "id": "reserve",
          "op": "tap",
          "target": "reserve_entry"
        },
        {
          "id": "pick_date",
          "op": "tap",
          "target": "date_cell"
        },
        {
          "id": "pick_party",
          "op": "tap",
          "target": "party_option"
        },
        {
          "id": "collect_slots",
          "op": "collect_list",
          "list": "time_slot_list",
          "item": "time_slot_item",
          "fields": {
            "time": "time_slot_label"
          },
          "until": {
            "end_of_list": true
          },
          "limit": 40,
          "max_scrolls": 3,
          "scroll_direction": "horizontal",
          "bind": "slots"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$venue.name",
            "$slots"
          ],
          "present": "table"
        }
      ]
    },
