    {
      "id": "shop.search_products",
      "version": 1,
      "risk": "R0",
      "computed_commit": "R0",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "상품 검색",
        "en": "Search products",
        "ja": "商品を検索",
        "zh-TW": "搜尋商品"
      },
      "summary_ko": "타깃의 검색창에 {query}를 입력해 검색하고, 광고를 제외한 상위 {limit}개 상품의 이름, 가격, 평점을 읽는다.",
      "params": {
        "query": {
          "type": "string",
          "required": true,
          "desc": "검색어"
        },
        "limit": {
          "type": "int",
          "default": 5,
          "min": 1,
          "max": 20
        }
      },
      "utterances": {
        "ko": [
          "타깃에서 {query} 검색해줘",
          "타깃에 {query} 얼마야?"
        ],
        "en": [
          "Search Target for {query}",
          "How much is {query} on Target?"
        ]
      },
      "script_ko": {
        "en": [
          "1. 타깃 앱 실행 (첫 화면으로 초기화)",
          "2. 'Search' 버튼 누르기",
          "3. 입력창에 {query} 입력",
          "4. 키보드 'search' 실행",
          "5. 목록 표시 대기 (최대 8초)",
          "6. 목록을 아래로 스크롤하며 [title, price, rating, ad] 수집 — {limit}개 모이면 멈춤, 광고 제외 → $results",
          "7. 종료 → 결과 $results (table)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "open_search",
          "op": "tap",
          "target": "search_entry"
        },
        {
          "id": "type_query",
          "op": "input_text",
          "target": "search_input",
          "value": "{query}"
        },
        {
          "id": "submit",
          "op": "press_ime",
          "action": "search"
        },
        {
          "id": "wait_results",
          "op": "wait_for",
          "target": "result_list",
          "timeout_ms": 8000
        },
        {
          "id": "collect_results",
          "op": "collect_list",
          "list": "result_list",
          "item": "result_item",
          "fields": {
            "title": "result_title",
            "price": "result_price",
            "rating": "result_rating",
            "ad": "result_ad_badge"
          },
          "filter": {
            "exclude_if": "ad"
          },
          "until": {
            "count": "{limit}"
          },
          "limit": "{limit}",
          "max_scrolls": 6,
          "bind": "results"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$results"
          ],
          "present": "table"
        }
      ]
    },
    {
      "id": "shop.add_to_cart",
      "version": 1,
      "risk": "R1",
      "computed_commit": "R0",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "상품 검색 후 장바구니 담기",
        "en": "Search and add to cart",
        "ja": "検索してカートに入れる",
        "zh-TW": "搜尋並加入購物車"
      },
      "summary_ko": "타깃에서 {query}를 검색하고, 사용자가 고른(또는 말한 순번의) 상품을 열어 장바구니 담기를 누른다. 옵션 선택이 필요하면 사용자에게 넘긴다.",
      "params": {
        "query": {
          "type": "string",
          "required": true,
          "desc": "검색어"
        },
        "pick_index": {
          "type": "int",
          "required": false,
          "min": 1,
          "max": 20,
          "desc": "사용자가 말한 순번(예: 두 번째). 없으면 사용자가 목록에서 선택"
        }
      },
