      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "상품 검색",
        "en": "Search products",
        "ja": "商品を検索",
        "zh-TW": "搜尋商品"
      },
      "summary_ko": "테무의 검색창에 {query}를 입력해 검색하고, 광고를 제외한 상위 {limit}개 상품의 이름, 가격, 평점을 읽는다.",
      "params": {
        "query": {
          "type": "string",
          "required": true,
          "desc": "검색어"
        },
