          "type": "int",
          "default": 5,
          "min": 1,
          "max": 20
        }
      },
      "utterances": {
        "ko": [
          "테무에서 {query} 검색해줘",
          "테무에 {query} 얼마야?"
        ],
        "en": [
          "Search Temu for {query}",
