      "title": {
        "ko": "메뉴/가게 검색",
        "en": "Search restaurants",
        "ja": "お店を検索",
        "zh-TW": "搜尋餐廳"
      },
      "summary_ko": "우버이츠의 검색창에 {query}를 입력해 검색하고 상위 {limit}개 가게의 이름, 평점, 예상 배달시간, 배달비를 읽는다.",
      "params": {
        "query": {
          "type": "string",
          "required": true,
          "desc": "메뉴 또는 가게 이름"
        },
        "limit": {
          "type": "int",
          "default": 5,
          "min": 1,
          "max": 20
        }
      },
      "utterances": {
        "ko": [
          "우버이츠에서 {query} 시킬 데 찾아줘"
        ],
        "en": [
          "Find {query} places on Uber Eats"
        ],
        "ja": [
          "Uber Eatsで{query}のお店を探して"
        ],
        "zh-TW": [
          "在Uber Eats找{query}"
        ]
      },
      "script_ko": {
        "en": [
          "1. 우버이츠 앱 실행 (첫 화면으로 초기화)",
          "2. 'Search' 버튼 누르기",
          "3. 입력창에 {query} 입력",
          "4. 키보드 'search' 실행",
          "5. 목록을 아래로 스크롤하며 [name, rating, eta, fee] 수집 — {limit}개 모이면 멈춤 → $stores",
          "6. 종료 → 결과 $stores (table)"
        ],
        "ja": [
          "1. 우버이츠 앱 실행 (첫 화면으로 초기화)",
          "2. '検索' 버튼 누르기",
          "3. 입력창에 {query} 입력",
          "4. 키보드 'search' 실행",
          "5. 목록을 아래로 스크롤하며 [name, rating, eta, fee] 수집 — {limit}개 모이면 멈춤 → $stores",
          "6. 종료 → 결과 $stores (table)"
        ],
        "zh-TW": [
          "1. 우버이츠 앱 실행 (첫 화면으로 초기화)",
          "2. '搜尋' 버튼 누르기",
          "3. 입력창에 {query} 입력",
          "4. 키보드 'search' 실행",
          "5. 목록을 아래로 스크롤하며 [name, rating, eta, fee] 수집 — {limit}개 모이면 멈춤 → $stores",
          "6. 종료 → 결과 $stores (table)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
