    {
      "id": "shop.reorder_to_cart",
      "version": 1,
      "risk": "R1",
      "computed_commit": "R0",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "지난 주문 다시 담기",
        "en": "Add a past order to cart again",
        "ja": "過去の注文をもう一度カートへ",
        "zh-TW": "再次購買過去訂單"
      },
      "summary_ko": "월마트의 주문 목록에서 {item_keyword}가 포함된 최근 주문을 찾아 재구매(다시 담기)를 누른다. 옵션 선택이 필요하면 사용자에게 넘긴다.",
      "params": {
        "item_keyword": {
          "type": "string",
          "required": true,
          "desc": "주문 상품 키워드. 없으면 가장 최근 주문"
        }
      },
      "utterances": {
        "ko": [
          "월마트에서 지난번 산 {item_keyword} 다시 장바구니에 담아줘"
        ],
        "en": [
          "Add the {item_keyword} I bought on Walmart to my cart again"
        ]
      },
      "script_ko": {
        "en": [
          "1. 월마트 앱 실행 (첫 화면으로 초기화)",
          "2. 'Account' 탭 선택",
          "3. 'Purchase history' 버튼 누르기",
          "4. 목록 표시 대기 (최대 8초)",
          "5. 목록에서 [이름]에 '{item_keyword}'가 포함된 항목 찾기 — 여러 개면 첫 항목(주문 목록은 최신순 정렬이므로 가장 최근 주문을 선택(결정론적)), 없으면 중단 → $order",
          "6. 'Reorder'가 보이면",
          "   → 그렇다면:",
          "    6.1. 'Reorder' 버튼 누르기 ($order 안에서)",
          "   → 아니라면:",
          "    6.1. 선택된 항목($order) 누르기",
          "    6.2. 'Reorder' 버튼 누르기",
          "7. 'Select'가 보이면",
          "   → 그렇다면:",
          "    7.1. [사용자에게 인계] \"옵션을 선택하고 담기 버튼을 직접 눌러주세요.\", 'Added to cart' 확인까지 대기",
          "8. 종료 → 결과 $order.title (none)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_my",
          "op": "tap",
          "target": "my_page_entry"
        },
        {
          "id": "go_orders",
          "op": "tap",
          "target": "orders_entry"
        },
        {
          "id": "wait_orders",
          "op": "wait_for",
          "target": "order_list",
          "timeout_ms": 8000
        },
        {
          "id": "match_order",
          "op": "find_in_list",
          "list": "order_list",
          "item": "order_item",
          "match": {
            "field": "order_item_title",
            "op": "contains",
            "value": "{item_keyword}"
          },
          "on_multiple": "first",
          "first_reason": "주문 목록은 최신순 정렬이므로 가장 최근 주문을 선택(결정론적)",
          "on_none": "abort",
          "bind": "order"
        },
        {
          "id": "tap_reorder",
          "op": "if_visible",
          "target": "reorder_button",
          "within": "$order",
          "then": [
            {
              "id": "reorder_in_list",
              "op": "tap",
              "target": "reorder_button",
              "within": "$order"
            }
          ],
          "else": [
            {
              "id": "open_order",
              "op": "tap",
              "target": "$order"
            },
            {
              "id": "reorder_in_detail",
              "op": "tap",
              "target": "reorder_button"
            }
          ]
        },
        {
          "id": "options",
          "op": "if_visible",
          "target": "option_sheet",
          "then": [
            {
              "id": "handoff_options",
              "op": "handoff_to_user",
              "instruction": {
                "ko": "옵션을 선택하고 담기 버튼을 직접 눌러주세요.",
                "en": "Pick the options and tap Add yourself.",
                "ja": "オプションを選んで追加してください。",
                "zh-TW": "請選擇規格後自行加入。"
              },
              "success_marker": "cart_added_marker",
              "timeout_ms": 180000
            }
          ]
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$order.title"
          ],
          "present": "none"
        }
      ]
    },
    {
      "id": "shop.open_cancel_return",
      "version": 1,
      "risk": "R3",
      "computed_commit": "R3",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "주문 취소/반품 신청 화면 열기",
        "en": "Open cancel/return for an order",
        "ja": "キャンセル・返品画面を開く",
        "zh-TW": "開啟取消/退貨"
      },
      "summary_ko": "월마트의 주문 목록에서 사용자가 고른 주문의 취소/반품 화면까지 이동한 뒤, 사유 선택과 신청 확정은 사용자가 직접 하게 한다.",
      "params": {
        "limit": {
          "type": "int",
          "default": 10,
          "min": 1,
          "max": 20
        }
      },
      "utterances": {
        "ko": [
          "월마트 주문 취소하고 싶어",
          "월마트 반품 신청 화면 열어줘"
        ],
        "en": [
          "I want to cancel or return an Walmart order"
        ]
      },
      "script_ko": {
        "en": [
          "1. 월마트 앱 실행 (첫 화면으로 초기화)",
          "2. 'Account' 탭 선택",
          "3. 'Purchase history' 버튼 누르기",
          "4. 목록 표시 대기 (최대 8초)",
          "5. 목록을 아래로 스크롤하며 [title, date, status] 수집 — {limit}개 모이면 멈춤 → $orders",
          "6. [사용자 선택] $orders을 보여주고 사용자가 직접 고름 → $order",
          "7. [사용자 확인] \"{order.title} 주문의 취소/반품 화면으로 이동합니다.\" — 표시: $order.title / 취소하면 중단",
          "8. 선택된 항목($order) 누르기",
          "9. 'Return or replace items' 버튼 누르기",
          "10. [사용자에게 인계] \"사유를 선택하고 신청 버튼을 직접 눌러 주세요.\" — 사용자가 'Submit'를 직접 누름, 'Cancelled' 확인까지 대기",
          "11. 종료 → 결과 $order.title (none)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_my",
          "op": "tap",
          "target": "my_page_entry"
        },
        {
          "id": "go_orders",
          "op": "tap",
          "target": "orders_entry"
        },
        {
          "id": "wait_orders",
          "op": "wait_for",
          "target": "order_list",
          "timeout_ms": 8000
        },
        {
          "id": "collect_orders",
          "op": "collect_list",
          "list": "order_list",
          "item": "order_item",
          "fields": {
            "title": "order_item_title",
            "date": "order_item_date",
            "status": "order_item_status"
          },
          "until": {
            "count": "{limit}"
          },
          "limit": "{limit}",
          "max_scrolls": 6,
          "bind": "orders"
        },
        {
          "id": "choose_order",
          "op": "choose_by_user",
          "from": "$orders",
          "display": [
            "title",
            "date",
            "status"
          ],
          "bind": "order"
        },
        {
          "id": "confirm",
          "op": "confirm_with_user",
          "summary": {
            "ko": "{order.title} 주문의 취소/반품 화면으로 이동합니다.",
            "en": "Open cancel/return for {order.title}?",
            "ja": "{order.title}のキャンセル・返品画面に進みます。",
            "zh-TW": "將開啟{order.title}的取消/退貨。"
          },
          "show": [
            "$order.title"
          ]
        },
        {
          "id": "open_order",
          "op": "tap",
          "target": "$order"
        },
        {
          "id": "tap_cancel",
          "op": "tap",
          "target": "cancel_return_button"
        },
        {
          "id": "handoff",
          "op": "handoff_to_user",
          "instruction": {
            "ko": "사유를 선택하고 신청 버튼을 직접 눌러 주세요.",
            "en": "Choose a reason and submit it yourself.",
            "ja": "理由を選んで申し込みボタンを押してください。",
            "zh-TW": "請選擇原因並自行送出。"
          },
          "commit_anchor": "cancel_submit_button",
          "success_marker": "cancel_done_marker",
          "timeout_ms": 600000
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$order.title"
          ],
          "present": "none"
        }
      ]
    }
  ]
}

