      "summary_ko": "구름이 정기 조사 결과(요약 글 + PDF)를 그 앱의 공유 화면으로 넘기고, 공유 대상 목록에서 {chat_name} 대화방을 찾아 고른 뒤 사용자 확인(또는 그 보내기 설정의 동의) 후 보낸다.",
      "params": {
        "chat_name": {
          "type": "string",
          "required": true,
          "desc": "대화방 이름(정기 조사 보내기 설정에서 고른 것)"
        }
      },
      "utterances": {},
      "script_ko": {},
      "steps": [
        {
          "id": "open_share",
          "op": "open_share"
        },
        {
          "id": "wait_list",
          "op": "wait_for",
          "target": "share_list",
          "timeout_ms": 10000
        },
        {
          "id": "search",
          "op": "if_visible",
          "target": "share_search_input",
          "then": [
            {
              "id": "type_name",
              "op": "input_text",
              "target": "share_search_input",
              "value": "{chat_name}"
            }
          ],
          "else": [
            {
              "id": "search_open",
              "op": "if_visible",
              "target": "share_search",
              "then": [
                {
                  "id": "tap_search",
                  "op": "tap",
                  "target": "share_search"
                },
                {
                  "id": "type_name2",
                  "op": "input_text",
                  "target": "share_search_input",
                  "value": "{chat_name}"
                }
              ]
            }
          ]
        },
        {
          "id": "pick_chat",
          "op": "find_in_list",
          "list": "share_list",
          "item": "share_item",
          "match": {
            "field": "share_item_name",
            "op": "equals",
            "value": "{chat_name}"
          },
          "on_multiple": "ask_user",
          "on_none": "abort",
          "bind": "chat"
        },
        {
          "id": "select_chat",
          "op": "tap",
          "target": "$chat"
        },
        {
          "id": "confirm",
          "op": "confirm_with_user",
          "summary": {
            "ko": "‘{chat_name}’ 대화방에 정기 조사 결과(요약과 PDF)를 보냅니다.",
            "en": "Send the research results (summary and PDF) to the chat ‘{chat_name}’?",
            "ja": "「{chat_name}」に定期調査の結果(要約とPDF)を送信します。",
            "zh-TW": "將把定期調查結果(摘要與PDF)傳送到「{chat_name}」。"
          },
          "show": [
            "$chat.name"
          ]
        },
        {
          "id": "send",
          "op": "tap",
          "target": "share_send_button"
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$chat.name"
          ],
          "present": "none"
        }
      ]
    }
  ]
}

