      ]
    },
    {
      "id": "shop.open_cancel_return",
      "version": 1,
      "risk": "R3",
      "computed_commit": "R3",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "주문 취소/반품 신청 화면 열기",
        "en": "Open cancel/return for an order",
        "ja": "キャンセル・返品画面を開く",
        "zh-TW": "開啟取消/退貨"
      },
      "summary_ko": "야후 쇼핑의 주문 목록에서 사용자가 고른 주문의 취소/반품 화면까지 이동한 뒤, 사유 선택과 신청 확정은 사용자가 직접 하게 한다.",
      "params": {
        "limit": {
          "type": "int",
          "default": 10,
          "min": 1,
          "max": 20
        }
      },
      "utterances": {
        "ko": [
          "야후 쇼핑 주문 취소하고 싶어",
          "야후 쇼핑 반품 신청 화면 열어줘"
        ],
        "ja": [
          "Yahoo!ショッピングの注文をキャンセルしたい"
        ]
      },
      "script_ko": {
        "ja": [
          "1. 야후 쇼핑 앱 실행 (첫 화면으로 초기화)",
          "2. 'マイページ' 탭 선택",
          "3. '注文履歴' 버튼 누르기",
          "4. 목록 표시 대기 (최대 8초)",
          "5. 목록을 아래로 스크롤하며 [title, date, status] 수집 — {limit}개 모이면 멈춤 → $orders",
          "6. [사용자 선택] $orders을 보여주고 사용자가 직접 고름 → $order",
          "7. [사용자 확인] \"{order.title} 주문의 취소/반품 화면으로 이동합니다.\" — 표시: $order.title / 취소하면 중단",
          "8. 선택된 항목($order) 누르기",
          "9. 'キャンセル' 버튼 누르기",
          "10. [사용자에게 인계] \"사유를 선택하고 신청 버튼을 직접 눌러 주세요.\" — 사용자가 '申し込む'를 직접 누름, '受け付けました' 확인까지 대기",
          "11. 종료 → 결과 $order.title (none)"
        ]
      },
      "steps": [
        {
          "id": "launch",
          "op": "launch_app",
          "reset": true
        },
        {
          "id": "go_my",
          "op": "tap",
          "target": "my_page_entry"
        },
        {
          "id": "go_orders",
          "op": "tap",
          "target": "orders_entry"
        },
        {
          "id": "wait_orders",
          "op": "wait_for",
          "target": "order_list",
          "timeout_ms": 8000
        },
        {
          "id": "collect_orders",
          "op": "collect_list",
          "list": "order_list",
          "item": "order_item",
          "fields": {
            "title": "order_item_title",
            "date": "order_item_date",
            "status": "order_item_status"
          },
          "until": {
            "count": "{limit}"
          },
          "limit": "{limit}",
          "max_scrolls": 6,
          "bind": "orders"
        },
        {
          "id": "choose_order",
          "op": "choose_by_user",
          "from": "$orders",
          "display": [
            "title",
            "date",
            "status"
          ],
          "bind": "order"
        },
        {
          "id": "confirm",
          "op": "confirm_with_user",
          "summary": {
            "ko": "{order.title} 주문의 취소/반품 화면으로 이동합니다.",
            "en": "Open cancel/return for {order.title}?",
            "ja": "{order.title}のキャンセル・返品画面に進みます。",
            "zh-TW": "將開啟{order.title}的取消/退貨。"
          },
          "show": [
            "$order.title"
          ]
        },
        {
          "id": "open_order",
          "op": "tap",
          "target": "$order"
        },
        {
          "id": "tap_cancel",
          "op": "tap",
          "target": "cancel_return_button"
        },
        {
          "id": "handoff",
          "op": "handoff_to_user",
          "instruction": {
            "ko": "사유를 선택하고 신청 버튼을 직접 눌러 주세요.",
            "en": "Choose a reason and submit it yourself.",
            "ja": "理由を選んで申し込みボタンを押してください。",
            "zh-TW": "請選擇原因並自行送出。"
          },
          "commit_anchor": "cancel_submit_button",
          "success_marker": "cancel_done_marker",
          "timeout_ms": 600000
        },
        {
          "id": "done",
          "op": "end",
          "output": [
            "$order.title"
          ],
          "present": "none"
        }
      ]
    }
  ]
}

