        {
          "id": "wait_results",
          "op": "wait_for",
          "target": "result_list",
          "timeout_ms": 15000
        },
        {
          "id": "collect_results",
          "op": "collect_list",
          "list": "result_list",
          "item": "result_item",
          "fields": {
            "name": "result_name",
            "price": "result_price",
            "rating": "result_rating",
