    {
      "id": "travel.my_bookings",
      "version": 1,
      "risk": "R0",
      "computed_commit": "R0",
      "trigger": "user_command",
      "side_effects": [],
      "explicit_target": false,
      "title": {
        "ko": "예약 내역 확인",
        "en": "My bookings",
        "ja": "予約を確認",
        "zh-TW": "查看我的預訂"
      },
      "summary_ko": "여기어때의 예약내역(여행) 탭을 열고 예약의 이름, 날짜, 상태를 읽는다.",
      "params": {},
      "utterances": {
        "ko": [
          "여기어때 예약 내역 보여줘"
        ]
      },
      "script_ko": {
        "ko": [
          "1. 여기어때 앱 실행 (첫 화면으로 초기화)",
          "2. '예약내역' 탭 선택",
          "3. 목록을 아래로 스크롤하며 [name, dates, status] 수집 — 목록 끝까지 → $bookings",
          "4. 종료 → 결과 $bookings (table)"
